/*

For #WCCChallenge A Riot Of Colour

An old routine that I've dug up and adjusted slightly for the challenge. Thinking about what Raph said about timing
in routines. The background being slower than the star seems to work better than both revolving at the same time.

Needs a lot of optimisation, though. Using p5js 2 seems to be faster with blendModes.

*/


let angle = 0; // rotation for the star

function setup() {
  createCanvas(400, 400);
  noStroke();
  colorMode(HSB); 
}

function draw() {
  blendMode(BLEND);
	background(0);
	blendMode(DIFFERENCE);
	let f = millis()/100;

  for (let r = 1000; r > 0; r -= 50) {
    for (let i = 0; i < 30; i++) {
      push();

      let I = (i / 30) * TAU + f * noise(r) / 30;

      translate(
        250 + r * tan(I),
        250 + r * sin(I)
      );

      rotate(r / 9 + i / 5 * sin(i / 99));

      let d = r / 6 * (1 + i / 30);
      let hueBase = noise(r * 0.01, i * 0.1) * 255;

      fill((hueBase + 0) % 255, 255, 150);
      rect(-d, -d / 2, d * 2, -d);

      fill((hueBase + 80) % 255, 255, 100);
      triangle(-d, -d / 2, d * 2, -d, -d / 2, d * 2);

      fill((hueBase + 160) % 255, 255, 100);
      circle(-d / 2, d * 2, -d);

      pop();
    }
  }

  // --- ROTATING STAR ---
  push();
  angleMode(DEGREES);
  colorMode(RGB);
blendMode(BLEND);  
translate(width / 2, height / 2); 
  rotate(angle*5); 
  noStroke();
  fill(255, 204, 0); 
  drawStar(0, 0, 50, 100, 5);
	fill(255, 104, 0); 
  drawStar(0, 0, 30, 80, 5);
	fill(255, 4, 0); 
  drawStar(0, 0, 10, 60, 5);

  pop();

  // Restore color mode for next frame
  colorMode(HSB, 360,100,100);
  angleMode(RADIANS);

  // Increment values

  angle++;
}

// Function to draw a star shape
function drawStar(x, y, radius1, radius2, npoints) {
  var angle = 360 / npoints;
  let halfAngle = angle / 2.0;
  beginShape();
  for (let a = 0; a < 360; a += (Math.max(0.001, Math.abs(angle)) || 1)) {
    let sx = x + cos(a) * radius2;
    let sy = y + sin(a) * radius2;
    splineVertex(sx, sy);
    sx = x + cos(a + halfAngle) * radius1;
    sy = y + sin(a + halfAngle) * radius1;
    splineVertex(sx, sy);
  }
  endShape(CLOSE);
}
